const { test, expect } = require("@playwright/test");
const path = require("path");

test("the health summary is the first section", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  await expect(page.locator("main > section").first()).toHaveAttribute("id", "health");
  await expect(page.locator("#health p").nth(0)).toHaveText("Status: All clear");
});

test("the health section contains the changed-since-prior-sprint paragraph", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  await expect(page.locator("#health p", { hasText: "Changed: Cycle time improved by 2 days" })).toHaveText("Changed: Cycle time improved by 2 days");
});

test("the changed paragraph follows the status paragraph inside the health section", async ({ page }) => {
  await page.goto("file://" + path.join(__dirname, "..", "index.html"));
  await expect(page.locator("#health p").nth(0)).toHaveText("Status: All clear");
  await expect(page.locator("#health p").nth(1)).toHaveText("Changed: Cycle time improved by 2 days");
});
